using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace EasyEcs;

// Component storage: one dense column (T[]) per component type, indexed by entity id, plus the structural changes
// that move an entity between archetypes. The public T1..T9 overloads are generated by EasyEcs.Generator.
public sealed partial class World
{
    // Indexed by ComponentType<T>.Bit; null until the type is first used in this world.
    internal Array[] Components = [];

    // Per column: whether T holds managed references (only those need clearing on remove/destroy to release them).
    private bool[] _columnHasReferences = [];

    /// <summary>
    /// Bit of <typeparamref name="T"/>, making sure this world has a column covering every id. Must be called inside
    /// the structural lock.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal ushort PrepareColumn<T>() where T : struct, IComponent
    {
        ushort bit = ComponentType<T>.Bit;
        var columns = Components;
        if (bit >= columns.Length || columns[bit] == null)
            CreateColumn<T>(bit);
        return bit;
    }

    /// <summary>Typed column of component <typeparamref name="T"/>; the column must exist.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal T[] Column<T>(ushort bit) where T : struct, IComponent =>
        Unsafe.As<T[]>(Unsafe.Add(ref MemoryMarshal.GetArrayDataReference(Components), bit));

    /// <summary>Ref to <typeparamref name="T"/> of entity <paramref name="id"/> without bounds checks.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal ref T ColumnRef<T>(ushort bit, int id) where T : struct, IComponent =>
        ref Unsafe.Add(ref MemoryMarshal.GetArrayDataReference(Column<T>(bit)), id);

    /// <summary>Add one component bit: follows the cached archetype edge (no mask hashing). Inside the structural lock.</summary>
    internal void AddBit(int id, ushort bit)
    {
        var from = MetaRef(id).Archetype;
        if (!from.ComponentMask.HasBit(bit))
            MoveToArchetype(id, ArchetypeAfterAdd(from, bit));
    }

    /// <summary>
    /// Add several component bits in one archetype transition. The target archetype is cached per (source archetype,
    /// <paramref name="signature"/>), so only the first call of a signature from an archetype builds a mask. Inside
    /// the structural lock.
    /// </summary>
    internal void AddBits(int id, ReadOnlySpan<ushort> bits, int signature)
    {
        var from = MetaRef(id).Archetype;
        MoveToArchetype(id, from.GetAddSetEdge(signature) ?? CreateSetEdge(from, bits, signature, add: true));
    }

    /// <summary>Remove one component bit, releasing its managed data. A missing component is ignored. Inside the structural lock.</summary>
    internal void RemoveBit(int id, ushort bit)
    {
        var from = MetaRef(id).Archetype;
        if (!from.ComponentMask.HasBit(bit)) return;
        MoveToArchetype(id, ArchetypeAfterRemove(from, bit));
        ReleaseComponents(id, [bit]);
    }

    /// <summary>
    /// Remove component bits in one archetype transition (cached per source archetype and
    /// <paramref name="signature"/>), releasing managed data of removed components. Missing components are ignored.
    /// Inside the structural lock.
    /// </summary>
    internal void RemoveBits(int id, ReadOnlySpan<ushort> bits, int signature)
    {
        var from = MetaRef(id).Archetype;
        var target = from.GetRemoveSetEdge(signature) ?? CreateSetEdge(from, bits, signature, add: false);
        if (ReferenceEquals(target, from)) return;
        MoveToArchetype(id, target);
        ReleaseComponents(id, bits);
    }

    /// <summary>
    /// Clear component data of <paramref name="id"/> in columns holding managed references, so removed or destroyed
    /// components do not keep objects alive. Unmanaged columns are left as is (Add/Set overwrite them).
    /// </summary>
    private void ReleaseComponents(int id, ReadOnlySpan<ushort> bits)
    {
        var hasReferences = _columnHasReferences;
        for (int i = 0; i < bits.Length; i++)
        {
            int bit = bits[i];
            if (bit < hasReferences.Length && hasReferences[bit])
                Array.Clear(Components[bit], id, 1);
        }
    }

    /// <summary>Create the column of <typeparamref name="T"/> (cold path). Inside the structural lock.</summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private void CreateColumn<T>(ushort bit) where T : struct, IComponent
    {
        if (bit >= Components.Length)
        {
            int length = Math.Max(Components.Length * 2, bit + 1);
            Array.Resize(ref Components, length);
            Array.Resize(ref _columnHasReferences, length);
        }

        Components[bit] = new T[Meta.Length];
        _columnHasReferences[bit] = RuntimeHelpers.IsReferenceOrContainsReferences<T>();
        StorageVersion++;
    }
}
